@startuml

class Airline {
  + ID : int
}

class Flight {
  + ID : int
  + departure_time : time
  + arrival_time : time
}

class Airport {
  + ID : int
}

class Aircraft {
  + Type : string
  + State : string
  + Position : string
}

class Pilot {
  + ExperienceLevel : int
}

class AeroplaneType {
  + Name : string
}

Airline "1" -- "0..*" Flight : operates
Airline "1" -- "0..*" Aircraft : owns
Flight "0..*" -- "1" Airport : departs from
Flight "0..*" -- "1" Airport : arrives at
Flight "0..*" -- "1" Pilot : captain
Flight "0..*" -- "1" Pilot : co-pilot
Flight "0..*" -- "1" Aircraft : uses
Aircraft "0..*" -- "1" AeroplaneType : is of type

@enduml

